ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["barks_horde_1"] = {
{"HORDE_INCOMING","reg=civilian,family,worker,rescue",{"A crowd! A big crowd of them coming!","They're coming this way! Hundreds! Run!","Oh no, oh no - too many, we have to go"}},
{"HORDE_INCOMING","reg=law|world=cars",{"Large group approaching! Move to the vehicles!"}},
{"HORDE_INCOMING","reg=law",{"Heavy numbers coming this way - we're leaving","Horde incoming, all units, fall back to the rally point","They're coming this way, repeat, they're headed toward us","Move, move, move, they're closing in","Dispatch, we're being approached by a large group of infected, need an exit route","Deputies, on me, we leave the area now, they are on the move","All units, abort, abort, withdraw, large group inbound","They're coming, they're coming, keep your heads and pull back"}},
{"HORDE_INCOMING","reg=swat",{"Mass approach - withdraw","Horde incoming, fallback, fallback","They're approaching, pull back, now","Mass of infected closing, withdraw to secondary","Inbound, inbound, too many of them, fall back","Moving, moving, moving, they are on us","Let's go, let's go, they're closing"}},
{"HORDE_INCOMING","reg=military",{"Horde incoming! Fall back to the transport!","They're coming in force! Pull out!","Horde inbound, sir, request permission to withdraw","Large group approaching our position, sir, we need to move","Pull back, pull back, we are leaving this position","They've turned toward us, sir, ETA minutes","Squad, on me, fall back now, no heroes","We're being flanked by a crowd, sir, we need to fall back"}},
{"HORDE_INCOMING","reg=elite",{"Large crowd approaching - withdraw","Horde inbound, displacing","Fall back, secondary position","Large group approaching, moving"}},
{"HORDE_INCOMING","reg=outlaw,raider,gang,club,crime,prison",{"Horde! Horde coming! Go, go!","Hell no, I'm not fighting that - leave!","Look at that crowd! Let's go!","Here they come, here they come, fuck, here they come!","RUN, you stupid bastards, they're coming!","Who made that fucking noise?! Who?!","We gotta go, we gotta GO, they're almost here","Grab the loot and move, MOVE, no time to count it","They're headed this way! This way! Let's go!","Oh, hell no, hell no, we ain't dying here for this, GO","Move your ass or you're dead!","You hear that? That's them, that's them coming","Boss, Boss, they're coming, what do we do?!","Everybody shut up and move, quiet but quick","Shit, shit, shit, I don't want to get boxed in! Keep moving!","Leave the damn stuff, the stuff doesn't matter, GO!","They're coming, they're slow, but there's like a hundred of 'em"}},
{"HORDE_INCOMING","reg=civilian,family,worker,rescue|tmp=fresh|mood=fear",{"They're coming, they're coming, they're all coming this way!!","RUN! Run run run run, they're headed straight for us!","Oh God, they HEARD us!","Which way, which way, WHICH WAY do we go?!","Move! MOVE! Get up, get up, there's no time!","I can hear them from here, that low roar... oh God","Oh Jesus, please no, we can't outrun that many, we CAN'T","Don't just stand there, GO! GO! They're almost on us!","Mommy, they're coming, make them stop, make them stoooop","It's the noise, it was the noise, somebody made noise, who made noise?!","We're done- it's too late for-- no, GO, GO!","I can feel the ground shaking, or is that just me? Is it me?","Hurry! Hurry up! Please, please, hurry up!!","They're closing, they're closing, they're not slowing down at all-"}},
{"HORDE_INCOMING","reg=civilian,family,worker,rescue|tmp=fresh",{"Here they come, everybody up, up!","The crowd is heading our way, we have to leave, now","They've picked us up, I think, they've changed direction","Pack up, pack up, grab what you can, they're coming","I don't like this, that's it, we're moving","Quick, quick, up, they're getting closer","Stay with me, don't lose me in this!","It's all coming toward us, all of it, let's go!","Leave it, leave the bags, just go, they're coming","They're coming! Oh God, we can't stay here!","Don't look back, just keep going, don't look back"}},
{"HORDE_INCOMING","reg=civilian,family,worker,rescue|tmp=seasoned",{"Horde's on the move, headed our way, pack it up","We've got a few minutes at most, grab and go","They've turned toward us, no more waiting","Heads up, that crowd's coming for us, time to move","Walk, don't run, running makes noise, but walk FAST","Come on, everybody, tight formation, we leave quietly","The noise brought them, never again, we leave now","They're coming, but they're slow, we can still get clear","Bring the rear in, they're closing, let's go","Don't fight it, don't even try, just get out of their path","Okay, here they come, you know what to do"}},
{"HORDE_INCOMING","reg=civilian,family,worker,rescue|tmp=seasoned|mood=angry",{"Damn it, damn it, somebody made noise, I KNEW it","Who was the idiot who fired? WHO?! Now look!","Here they come, thanks a lot, thanks a LOT"}},
{"HORDE_INCOMING","reg=civilian,family,worker,rescue|tmp=seasoned|mood=grim",{"Here comes the tide, and we can't stop it...","They always come, no matter how quiet you are, they always come"}},
{"HORDE_INCOMING","reg=civilian,family,worker,rescue|mood=calm",{"They're coming, but we have time, keep calm and pick up your things","Everyone, quietly, they're heading toward us, we're going to leave","Horde incoming, nothing we can't walk away from"}},
{"HORDE_INCOMING","role=family_elder",{"Oh, Lord, they're coming this way, leave me, leave me, go on","I can't go fast, children, you go, you go ahead","Help me up, help me up, please, they're coming"}},
{"HORDE_INCOMING","role=family_youth",{"Oh shit, oh shit, oh shit, they're coming!","Mom! Dad! They're coming, come ON!","Go, go, go, what are you waiting for?! THEY'RE COMING!"}},
{"HORDE_INCOMING","role=family_woman",{"Grab the children! Now! Now! They're coming!","Hold my hand, hold my hand, don't let go, we're running"}},
{"HORDE_INCOMING","role=family_man",{"Everyone behind me, we leave NOW, they're coming","Pick up the little ones, we're going, go, go, GO!"}},
{"HORDE_INCOMING","role=rescue_firefighter",{"Evacuate, evacuate, everyone move, they're coming this way","Move out in single file, they're heading toward us, no pushing","Heads up, heads up, move to the extraction point, on me"}},
{"HORDE_INCOMING","role=rescue_medical",{"I can't carry anyone, if you can walk, walk, if you can run, RUN","They're coming, take the injured with you, don't leave them"}},
{"HORDE_INCOMING","role=rescue_clergy",{"Let us go quietly, now, the Lord is with us, but move","Oh, Father, they're coming, let us leave this place"}},
{"HORDE_INCOMING","role=worker",{"They're heading right for us, grab your gear and let's get","Crap, crap, here they come, forget the tools, leave 'em","That's it, we're done here, everybody move"}},
{"HORDE_INCOMING","role=civilian_loner",{"They're coming, time I wasn't here","Horde on the move, I'm out"}},
{"HORDE_INCOMING","role=civilian_woman",{"They're coming, they're coming, quick, come with me","Oh no, no, they heard us, they heard us, we need to go"}},
{"HORDE_INCOMING","role=civilian_man",{"Here they come, let's move, I don't like those odds","Pick it up, they're coming, no time to argue"}},
{"HORDE_INCOMING","reg=law|tmp=seasoned",{"Large group heading our way, we're pulling back, quiet and quick","It's time to go, nobody hero, nobody stay behind","They're coming, let's get gone"}},
{"HORDE_INCOMING","role=soldier_green",{"They're coming! They're coming! Sir, they're coming right at us!","Oh God, oh God, we're gonna die, sir, we're gonna die here","I can see them, they're so many, sir, please, can we go?"}},
{"HORDE_INCOMING","role=soldier_nco",{"Squad, fall back, fall back, nobody runs, we move together","Get up, get up, grab your kit, we are leaving","Stay with me, trainee, breathe, we are leaving"}},
{"HORDE_INCOMING","role=deserter",{"I told you, I told you, I knew they'd find us","Great, they're coming, I'm out of here, you stay if you want","Not again, not AGAIN"}},
{"HORDE_INCOMING","role=militia",{"Here they come, boys, grab your stuff and go","We can't hold against that, pack it up, move","Fall back, fall back, y'all, they're coming for us"}},
{"HORDE_INCOMING","role=elite_delta",{"Inbound, displacing, now","Pulling back"}},
{"HORDE_INCOMING","reg=outlaw,raider,gang,club,crime,prison|tmp=fresh",{"They're coming, they're coming, please let's go, please","I want out, I want OUT of this, they're coming"}},
{"HORDE_INCOMING","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"Heh, let 'em come, let 'em come, they'll trip over each other... then again, no, let's go","Plenty of 'em, plenty, but I like my odds better elsewhere"}},
{"HORDE_INCOMING","role=raider_boss",{"Pack it up, we're moving, anybody who stalls gets left","We leave NOW, in order, no panic, no noise"}},
{"HORDE_INCOMING","role=gang_boss",{"Get up, get up, we're out, they're coming for us","Move as a unit, nobody drops behind, go"}},
{"HORDE_INCOMING","role=biker",{"Brothers, they're headed our way, mount up, move out","Jesus, here come the dead, saddle up, boys, saddle up"}},
{"HORDE_INCOMING","role=prisoner",{"They're coming for me! I ain't going back, I ain't!","Run! Run, man, run!"}},
{"HORDE_INCOMING","role=crime_member",{"Time to go, time to go, everyone, they're coming","Don't argue, don't ask, just move, they're coming"}},
{"HORDE_INCOMING","role=outlaw",{"Crap, here they come, git moving, y'all","Get on out of here, they'll swarm us if we stay"}},
{"HORDE_SPOTTED","reg=law",{"There's a whole crowd of those things!","That's too many of them. Don't get trapped","Lord, look at them all - back up slow","Big group of them heading this way - move!","Large group of infected, need backup, need a lot of backup","Dispatch, I've got a crowd, an infected crowd, count unknown, over","Mass casualty, mass infected, I'm not equipped for this","Horde ahead, don't fight them, repeat, don't fight them","That's well over fifty, deputies, fall back, now","They're massing, I can see them gathering, hundreds, all of them gathering","Radio it in, large number of infected moving this way","Sheriff, you need to see this, there's a whole crowd of them","Nothing we have stops that, I need to say it out loud, nothing stops that"}},
{"HORDE_SPOTTED","reg=swat",{"Large group, inbound!","Too many, we pull back","That's a crowd - fall back","Large group of infected, large group","Horde in sight, we don't fight them","Too many of them, too many of them, request guidance","Fifty-plus, fifty-plus, we don't have the ammo for this","Crowd, big, big crowd, pull back","Wave of them, hold the line, no, fall back"}},
{"HORDE_SPOTTED","reg=swat|world=vehicle",{"Dozens of them - get to the vehicle"}},
{"HORDE_SPOTTED","reg=military,elite",{"Large group of infected, moving our way!","That's too many - pull back!"}},
{"HORDE_SPOTTED","reg=military,elite|world=cars",{"Horde! Pull back to the trucks!"}},
{"HORDE_SPOTTED","reg=military,elite|world=road",{"Mass of infected on the road - fall back!"}},
{"HORDE_SPOTTED","reg=civilian,family,worker,rescue",{"Oh my God, there's so many","They're all coming! All of them!","Run! There's too many!","Oh Lord, look at all of them"}},
{"HORDE_SPOTTED","reg=raider,outlaw,gang,club,crime,prison",{"Whoa - nope, that's a lot of them","Big ugly crowd coming, let's book it","That's way too many - scatter!","Screw this - run!"}},
{"HORDE_SPOTTED","reg=civilian,family,worker,rescue|tmp=fresh|mood=fear",{"Oh no, oh NO, there's hundreds, there's HUNDREDS of them!","I can't count them, I can't count them, there's too many!","Oh Jesus, there's so many, they keep COMING, there's no end to it!","Jesus, it's like the whole town got up and walked!","Nobody move, nobody breathe, there's a whole crowd of them","We're dead, we're dead, we are so dead, look at that many!","Ohhh God, a herd, a HERD, mommy, a herd of them","It's a wave, it's a- just look at it, it's one big moving mass of them","No way, there can't be that many people left to turn!","There must be a hundred, a hundred and... oh, I stopped counting","Why are there so many? Where did they all COME from?","They're all walking the same way, all of them, together, like they know something","Please tell me that's not what I think it is, please","I think I'm gonna throw up, there's a whole crowd of them","It's like a whole congregation, except they're all... oh God"}},
{"HORDE_SPOTTED","reg=civilian,family,worker,rescue|tmp=fresh",{"Big bunch of them up ahead, get down","Don't make a sound, there's a crowd of dead ones ahead","Whoa... how many IS that?","We can't fight that, we can't, we have to go around","Quiet! Look at how many there are, quiet!","That's way too many for us, way, way too many","We need to go another way, there's a crowd and it's heading this way","A pack of them, maybe thirty, maybe more","Look at that group, they're all just walking together","A whole mob of them, I counted twenty and gave up","Is that a funeral? Why are there so many of them together?","Everyone get back, quietly, quietly, a big bunch is out there"}},
{"HORDE_SPOTTED","reg=civilian,family,worker,rescue|tmp=seasoned",{"Big group, fifty plus, don't draw them","Horde up there, ease back, don't make noise","That's a crowd, a real one, we leave right now","Dozens of them, just drifting, no hurry in them","Don't shoot, don't shout, we go the other way","Forty, fifty of 'em - we're not fighting that","That's more than we have bullets for, let's move","A big pack of them, headed for the noise somebody made","Count them later, move now","Seen smaller ones, never one like that, back off carefully","There's a bunch, east side, we sneak around","Too many to take on, we can slip past if we're careful"}},
{"HORDE_SPOTTED","reg=civilian,family,worker,rescue|tmp=seasoned|mood=grim",{"There's the horde... that's what everybody was whispering about","So that's where the rest of the town went...","Saw it coming for days, here it is, a crowd of the dead"}},
{"HORDE_SPOTTED","reg=civilian,family,worker,rescue|mood=calm",{"Large group ahead, we'll give it a wide berth","Quite a crowd out there, let's not be seen","A horde. Move slowly, keep your distance"}},
{"HORDE_SPOTTED","role=family_elder",{"Lord in Heaven, look at that, all of them, all of them once alive","So many, so many, they were somebody's children","Oh my... honey, don't you look at all that"}},
{"HORDE_SPOTTED","role=family_youth",{"Holy crap, holy CRAP, it's like a concert, a concert of dead people!","There's like a thousand of them! A thousand!","We can't fight that, right? We can't?! Please say we can't"}},
{"HORDE_SPOTTED","role=family_man",{"Get the kids back, there's a crowd, a big crowd, get them back","We're turning around, now, everyone, quietly"}},
{"HORDE_SPOTTED","role=family_woman",{"Oh, honey, there's so many, let's go, let's go quietly","I'm not going near that, take us the other way!"}},
{"HORDE_SPOTTED","role=rescue_firefighter",{"Mass of infected ahead, we are not fighting, repeat, not fighting","That's a crowd, the kind that overruns you, pull back","Large group, large group, stay out of their line"}},
{"HORDE_SPOTTED","role=rescue_medical",{"I can't treat a hundred people, I can't, oh God","I've treated sick folks my whole career, and those... there's nobody in there anymore"}},
{"HORDE_SPOTTED","role=rescue_clergy",{"A multitude, the Lord help us, a multitude of the dead","Hush now, children, quiet, don't let them hear us"}},
{"HORDE_SPOTTED","role=worker",{"Holy hell, a whole crowd of them, a hundred easy","Looks like the whole shift lined up, every last one of them","Aw man, we are not going near that, no sir"}},
{"HORDE_SPOTTED","role=civilian_loner",{"Crowd, big, I go around","That's a horde, a real one, I'm gone"}},
{"HORDE_SPOTTED","role=civilian_woman",{"So many... God... be quiet, be still","Don't make any noise, there's a big crowd coming this way"}},
{"HORDE_SPOTTED","role=civilian_man",{"Big bunch ahead, we don't want that fight","There must be sixty of them, back off, quietly"}},
{"HORDE_SPOTTED","reg=law|tmp=seasoned",{"Big crowd, hold position, don't fire","Count at least forty, I'd rather not find out the real number","Large group, calm down, back away slow"}},
{"HORDE_SPOTTED","reg=military",{"Horde sighted, horde sighted, sir, bearing north","Mass of infected, sir, I count thirty, forty, more, sir","Large group approaching, don't fight them, withdraw","We don't have the firepower for that, sir","Too many of them, sir, request orders","That's a battalion of the dead, sir, no joke"}},
{"HORDE_SPOTTED","role=soldier_green",{"Sir? Sir, how many are there? SIR HOW MANY?!","Oh God, there's too many, there's too many, sir, I can't count that high","Jesus, that's more than a platoon, it's a whole damn city of 'em"}},
{"HORDE_SPOTTED","role=soldier_nco",{"Large group, stay calm, nobody fires, back out the way we came","I count a lot, enough, we're withdrawing","Steady, trainee. Breathe, don't rush closer"}},
{"HORDE_SPOTTED","role=deserter",{"Fuck, fuck, THAT'S what's out there, no way","I knew it, I knew it, I knew it, we should have gone the other way","A hundred of them, and the Army left us in it, great"}},
{"HORDE_SPOTTED","role=militia",{"That's a big old herd of them, boys, we ain't taking that","Whoa, fall back, fall back easy, don't spook 'em"}},
{"HORDE_SPOTTED","reg=elite",{"Large group, avoid","Mass infected, noting position","Horde, pull back quietly"}},
{"HORDE_SPOTTED","role=elite_delta",{"Horde, no fighting, moving","Too many of them, withdraw"}},
{"HORDE_SPOTTED","reg=outlaw,raider,gang,club,crime,prison",{"Jesus Christ, look at all of 'em! Look at that!","Holy fuck, there's a whole army of dead assholes!","Nope, nope, nope, nope, nope, we are going the other way","How many are there?! Seriously, how many?!","Don't shoot, don't shoot, you'll bring every last one down on us","I'm not fighting that, you can fight that, I'm leaving","That's like a hundred of those things, Boss, a HUNDRED","Whoa, shut up, shut UP, everybody, quiet, quiet","Where'd they come from, huh? Where'd they all come from?!","A whole damn crowd, I never signed up for this","Oh, this is bad, this is so bad, that's too many to run from","Boys, we need a new plan, and we need it NOW"}},
{"HORDE_SPOTTED","reg=outlaw,raider,gang,club,crime,prison|tmp=fresh",{"Please, please can we go, please, there's so many","I'm gonna cry, I'm gonna cry, look at them"}},
{"HORDE_SPOTTED","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"Ha! That's a lot of meat, but not for us, let's go around","Pretty scary bunch, ain't they? Still not scarier than me","Let 'em pass, let 'em pass, we'll have our fun later"}},
{"HORDE_SPOTTED","role=raider_boss",{"Nobody fires, nobody shouts, we back out, now","That's a crowd, and I don't pay you to die on a crowd"}},
{"HORDE_SPOTTED","role=gang_boss",{"Eyes down, hands off the triggers, we go back","Not worth the bullets, back away, back away"}},
{"HORDE_SPOTTED","role=biker",{"That's a hell of a crowd, brothers, let's not ride into that","Whole parade of the dead, boys, turn around"}},
{"HORDE_SPOTTED","role=prisoner",{"Oh God, not again, not again, I didn't get out for this","There's so many, man, so MANY, I can't"}},
{"HORDE_SPOTTED","role=crime_member",{"That's too many, we regroup, I need to talk to the boss","We got a problem, a real problem, back away, back away"}},
{"HORDE_SPOTTED","role=outlaw",{"Well, hell, lookit all them, ain't nobody gonna fight that","That many? Nope, I'll take my chances somewhere else"}},
}
